  "recovered_c": "uint64_t fn_06(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint8_t k[8];\n  uint8_t s[256];\n  size_t j = 0;\n  if (out_cap < len) {\n    len = 0xffffffffffffffff;\n  } else {\n    for (size_t i = 0; i < 8; i++) {\n      k[i] = (uint8_t)(arg >> ((byte)(i << 3) & 0x3f));\n    }\n    for (size_t i = 0; i < 0x100; i++) {\n      s[i] = (uint8_t)i;\n    }\n    for (size_t i = 0; i < 0x100; i++) {\n      j = (uint)k[i & 7] + s[i] + j & 0xff;\n      uint8_t uVar1 = s[i];\n      s[i] = s[j];\n      s[j] = uVar1;\n    }\n    j = 0;\n    for (size_t n = 0; n < len; n++) {\n      j = (j + s[n % 0x100]) & 0xff;\n      uint8_t uVar2 = s[j];\n      s[j] = s[n % 0x100];\n      s[n % 0x100] = uVar2;\n      out[n] = in[n] ^ s[(s[j] + s[n % 0x100]) & 0xff];\n    }\n  }\n  return len;\n}"
